    op.execute("CREATE FUNCTION protect_reference_batch() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Immutable reference source'; END IF; IF ROW(NEW.id,NEW.tenant_id,NEW.legal_entity_id,NEW.created_at,NEW.source_system,NEW.source_version,NEW.actor_id,NEW.records) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.legal_entity_id,OLD.created_at,OLD.source_system,OLD.source_version,OLD.actor_id,OLD.records) THEN RAISE EXCEPTION 'Immutable reference source'; END IF; RETURN NEW; END; $$")
    op.execute('CREATE TRIGGER immutable_source BEFORE UPDATE OR DELETE ON reference_batches FOR EACH ROW EXECUTE FUNCTION protect_reference_batch()')

